package io.github.playmusic.data.api

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * 実キャプチャ（mitmproxy flows.flow #1252）の searchview/v3/search レスポンスから
 * 取り出した生バイト列でパーサーを検証する。
 */
class SpClientProtoSearchTest {

    private val searchResponseHex = ""

    private fun hexToBytes(hex: String): ByteArray {
        require(hex.length % 2 == 0)
        return ByteArray(hex.length / 2) { i -> hex.substring(i * 2, i * 2 + 2).toInt(16).toByte() }
    }

    @Test
    fun searchResponseCanBeParsedWithoutException() {
        val parsed = SpClientProto.parseSearchView(hexToBytes(searchResponseHex))
        assertFalse("at least one entity", parsed.isEmpty())
        val first = parsed.first()
        assertTrue(first.uri.startsWith("spotify:track:"))
        assertEquals("Smells Like Teen Spirit", first.name)
        assertNotNull("track のサブタイトルにアーティストが入る", first.artists.firstOrNull())
    }
}
